  'mistakes-p2' => 'कमजोर पासवर्ड का उपयोग करने से झूठी सुरक्षा उत्पन्न होती है। कंपनी2026 या पासवर्ड123 जैसा पासवर्ड तुरंत क्रैक हो जाता है।',
  'mistakes-p3' => 'पासवर्ड स्वयं भूल जाने से दस्तावेज़ अप्राप्य हो जाते हैं। पासवर्ड मैनेजर का उपयोग करके हमेशा सुरक्षित पासवर्ड रिकॉर्ड बनाए रखें।',
  'mistakes-p4' => 'उपयोगकर्ता पासवर्ड के बिना स्वामी पासवर्ड लागू करने से दस्तावेज़ फ़ाइल तक पहुंच रखने वाले किसी भी व्यक्ति के लिए दृश्यमान हो जाते हैं। संवेदनशील दस्तावेज़ों के लिए हमेशा दोनों सुरक्षा परतों का उपयोग करें।',
  'mistakes-p5' => 'सुरक्षा कार्यान्वयन का परीक्षण करने में विफल होने का अर्थ है समस्याओं का पता तभी चलना जब दस्तावेज़ों का उल्लंघन हो। हमेशा नमूना दस्तावेज़ों पर पासवर्ड सुरक्षा का परीक्षण करें।',
  'compliance-heading' => 'अनुपालन और कानूनी विचार',
  'compliance-p1' => 'विभिन्न विनियमों के लिए विशिष्ट सुरक्षा नियंत्रण की आवश्यकता होती है। HIPAA को चिकित्सा दस्तावेज़ों के लिए एन्क्रिप्शन की आवश्यकता होती है। जीडीपीआर को व्यक्तिगत डेटा के लिए उचित सुरक्षा उपायों की आवश्यकता होती है। राज्य गोपनीयता कानून तेजी से एन्क्रिप्शन को अनिवार्य कर रहे हैं।',
  'compliance-p2' => 'आवश्यक सुरक्षा स्तर निर्धारित करने के लिए अपने उद्योग नियमों से परामर्श लें। कुछ उद्योगों को विशिष्ट एन्क्रिप्शन मानकों या सुरक्षा प्रमाणपत्रों की आवश्यकता होती है।',
  'compliance-p3' => 'अनुपालन ऑडिट के लिए अपनी सुरक्षा प्रथाओं का दस्तावेज़ीकरण करें। प्रदर्शित करें कि आपने अपने दस्तावेज़ प्रकारों के लिए उचित नियंत्रण लागू किए हैं।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-p1' => 'पीडीएफ सुरक्षा आपके संगठन को डेटा उल्लंघनों और अनधिकृत पहुंच से बचाती है। मजबूत पासवर्ड, एन्क्रिप्शन और उचित प्रतिबंध लागू करने से यह सुनिश्चित होता है कि दस्तावेज़ गोपनीय रहें।',
  'conclusion-p2' => 'सभी संवेदनशील दस्तावेज़ों के लिए उपयोगकर्ता और स्वामी पासवर्ड से प्रारंभ करें। __COMPRESS_LINK__ के माध्यम से व्यापक सुरक्षा जोड़ें और दीर्घकालिक सुरक्षा के लिए अपने सुरक्षा वर्कफ़्लो में संग्रह करें। सुरक्षित साझाकरण प्रथाओं को लागू करें और सुरक्षा कार्यान्वयन के विस्तृत रिकॉर्ड बनाए रखें।',
  'conclusion-p3' => 'सुरक्षा में निवेश में प्रति दस्तावेज़ कुछ मिनट लगते हैं लेकिन महंगे उल्लंघनों से सुरक्षा मिलती है। अपने संगठन में पीडीएफ सुरक्षा को एक मानक अभ्यास बनाएं।',
);
